  1→/**
  2→ * @fileoverview WhatsApp transport adapter for the Fetch bridge.
  3→ *
  4→ * Responsibilities:
  5→ * - manage WhatsApp Web client lifecycle (auth, ready, disconnect, reconnect)
  6→ * - route inbound messages/reactions through security + handler pipeline
  7→ * - normalize transport edge cases (duplicate events, self-chat, media payloads)
  8→ * - send proactive task progress/question updates back to users
  9→ *
 10→ * @module bridge/client
 11→ * @see {@link Bridge} Runtime bridge class
 12→ */
 13→
 14→import pkg from 'whatsapp-web.js';
 15→const { Client, LocalAuth } = pkg;
 16→type Message = pkg.Message;
 17→type ClientType = InstanceType<typeof Client>;
 18→import { logger } from '../utils/logger.js';
 19→import { pipeline } from '../config/pipeline.js';
 20→import { SecurityGate, RateLimiter, validateInput } from '../security/index.js';
 21→import { handleMessage, initializeHandler, shutdown, registerWhatsAppSender } from '../handler/index.js';
 22→import { getTaskIntegration } from '../task/integration.js';
 23→import { getTaskManager } from '../task/manager.js';
 24→import { updateStatus, incrementMessageCount } from '../api/status.js';
 25→import { transcribeAudio, isTranscriptionAvailable } from '../transcription/index.js';
 26→import { analyzeImage, isVisionAvailable } from '../vision/index.js';
 27→import { composeTaskFileOpMessages, composeTaskProgressMessages, composeTaskQuestionMessages } from './progress-message.js';
 28→import * as fs from 'fs';
 29→import * as path from 'path';
 30→
 31→// =============================================================================
 32→// TASK EVENT INTERFACES
 33→// =============================================================================
 34→
 35→/** Payload shape for task:progress events */
 36→interface TaskProgressEvent {
 37→  sessionId?: string;
 38→  message?: string;
 39→}
 40→
 41→/** Payload shape for task:file_op events */
 42→interface TaskFileOpEvent {
 43→  sessionId?: string;
 44→  operation?: string;
 45→  path?: string;
 46→}
 47→
 48→/** Payload shape for task:question events */
 49→interface TaskQuestionEvent {
 50→  sessionId?: string;
 51→  question?: string;
 52→}
 53→
 54→// =============================================================================
 55→// CHROME LOCK CLEANUP
 56→// =============================================================================
 57→
 58→/**
 59→ * Remove stale Chromium singleton lock files under WhatsApp auth data.
 60→ *
 61→ * This runs before client init/re-init to avoid Chromium startup failures
 62→ * after unclean shutdowns.
 63→ *
 64→ * @param authPath - Path to the .wwebjs_auth directory
 65→ */
 66→function cleanupChromeLocks(authPath: string): void {
 67→  const lockNames = new Set(['SingletonLock', 'SingletonCookie', 'SingletonSocket']);
 68→
 69→  try {
 70→    if (!fs.existsSync(authPath)) {
 71→      return; // No auth directory yet, nothing to clean
 72→    }
 73→
 74→    // Find session directories (session / session-* folders)
 75→    const topEntries = fs.readdirSync(authPath, { withFileTypes: true });
 76→
 77→    for (const entry of topEntries) {
 78→      if (!entry.isDirectory() || !entry.name.startsWith('session')) continue;
 79→
 80→      const sessionPath = path.join(authPath, entry.name);
 81→
 82→      // Directories to scan: the session root and its Default/ subfolder
 83→      const dirsToScan = [sessionPath];
 84→      const defaultPath = path.join(sessionPath, 'Default');
 85→      try { if (fs.statSync(defaultPath).isDirectory()) dirsToScan.push(defaultPath); } catch { /* no Default dir */ }
 86→
 87→      for (const dir of dirsToScan) {
 88→        // readdirSync lists ALL directory entries including broken symlinks
 89→        let entries: string[];
 90→        try { entries = fs.readdirSync(dir); } catch { continue; }
 91→
 92→        for (const name of entries) {
 93→          if (!lockNames.has(name)) continue;
 94→          const lockPath = path.join(dir, name);
 95→          try {
 96→            fs.unlinkSync(lockPath);
 97→            logger.info(`🧹 Cleaned up stale Chrome lock: ${dir}/${name}`);
 98→          } catch (e) {
 99→            logger.warn(`Could not remove lock ${lockPath}: ${e}`);
100→          }
101→        }
102→      }
103→    }
104→  } catch (error) {
105→    logger.warn(`Could not clean Chrome locks: ${error}`);
106→  }
107→}
108→
109→// =============================================================================
110→// MESSAGE DEDUPLICATION
111→// =============================================================================
112→
113→/**
114→ * Deduplicate inbound `message_create` events by message id with TTL eviction.
115→ */
116→class MessageDeduplicator {
117→  private processedMessages = new Map<string, number>();
118→  private readonly TTL_MS = pipeline.deduplicationTtl;
119→  private cleanupTimer: ReturnType<typeof setInterval>;
120→
121→  constructor() {
122→    // Sweep every TTL interval instead of per-message
123→    this.cleanupTimer = setInterval(() => this.evict(), this.TTL_MS);
124→    this.cleanupTimer.unref();
125→  }
126→
127→  /**
128→   * Mark and check message id.
129→   *
130→   * @returns `true` if message id was not seen in the current TTL window
131→   */
132→  isNew(messageId: string): boolean {
133→    if (this.processedMessages.has(messageId)) {
134→      return false;
135→    }
136→    this.processedMessages.set(messageId, Date.now());
137→    return true;
138→  }
139→
140→  /** Remove cached ids older than TTL. */
141→  private evict(): void {
142→    const cutoff = Date.now() - this.TTL_MS;
143→    for (const [id, ts] of this.processedMessages) {
144→      if (ts <= cutoff) this.processedMessages.delete(id);
145→    }
146→  }
147→}
148→
149→// =============================================================================
150→// BRIDGE CLASS
151→// =============================================================================
152→
153→/**
154→ * Runtime wrapper around `whatsapp-web.js` client.
155→ *
156→ * Owns client lifecycle, event wiring, inbound security checks, and outbound
157→ * proactive messaging integration.
158→ */
159→export class Bridge {
160→  private client: ClientType;
161→  private securityGate: SecurityGate;
162→  private rateLimiter: RateLimiter;
163→  private deduplicator = new MessageDeduplicator();
164→  private reactionDedup = new Map<string, number>();
165→  private botRecentMessageIds: string[] = []; // LRU cache for bot sent messages
166→  private readonly maxBotRecentMessages = 1000;
167→  private isReady = false;
168→  private readyAt = 0;
169→  private readonly reactionWarmupMs = 60_000;
170→  private readonly reactionDedupTtlMs = 10_000;
171→
172→  // Reconnection state
173→  private reconnectAttempts = 0;
174→  private readonly maxReconnectAttempts = pipeline.maxReconnectAttempts;
175→  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
176→  private isReconnecting = false;
177→  private destroyed = false;
178→
179→  /**
180→   * Disconnection reasons that should not trigger automatic reconnect loops.
181→   *
182→   * QR retry exhaustion is an operator-driven state (no scan happened), not a
183→   * transient transport failure. Auto-retrying immediately just recreates QR
184→   * churn and reaches the same terminal reason again.
185→   */
186→  private shouldPauseAutoReconnect(reason: string): boolean {
187→    const normalized = reason.toLowerCase();
188→    return normalized.includes('max qrcode retries reached');
189→  }
190→
191→  constructor() {
192→    this.client = new Client({
193→      authStrategy: new LocalAuth({
194→        dataPath: '/app/data/.wwebjs_auth'
195→      }),
196→      // QR code settings - refresh every 20 seconds (default is 45)
197→      qrMaxRetries: 10,
198→      puppeteer: {
199→        headless: true,
200→        args: [
201→          '--no-sandbox',
202→          '--disable-setuid-sandbox',
203→          '--disable-dev-shm-usage',
204→          '--disable-accelerated-2d-canvas',
205→          '--no-first-run',
206→          '--no-zygote',
207→          '--disable-gpu'
208→        ]
209→      }
210→    });
211→
212→    // SecurityGate initialized in initialize() for async whitelist loading
213→    this.securityGate = null as unknown as SecurityGate;
214→    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
215→  }
216→
217→  /**
218→   * Initialize security, handler integrations, event listeners, and WhatsApp client.
219→   */
220→  async initialize(): Promise<void> {
221→    // Clean up any stale Chrome lock files from previous crashes
222→    cleanupChromeLocks('/app/data/.wwebjs_auth');
223→
224→    // Initialize security gate with Zero Trust Bonding whitelist
225→    this.securityGate = await SecurityGate.create();
226→
227→    // Initialize agentic handler
228→    await initializeHandler();
229→
230→    // Register WhatsApp sender for proactive messages (task completions, etc.)
231→    registerWhatsAppSender(async (userId: string, text: string) => {
232→      try {
233→        logger.info(`Sending proactive message to ${userId}`);
234→        const targetId = userId.includes('@') ? userId : `${userId}@c.us`;
235→        const sentMsg = await this.client.sendMessage(targetId, text);
236→        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
237→          this.trackBotMessage(sentMsg.id._serialized);
238→        }
239→        logger.success(`Proactive message sent to ${targetId}`);
240→      } catch (err) {
241→        logger.error(`Failed to send proactive WhatsApp message to ${userId}`, err);
242→      }
243→    });
244→
245→    this.setupEventHandlers();
246→    this.setupTaskProgressListeners();
247→    await this.client.initialize();
248→  }
249→
250→  /**
251→   * Register WhatsApp client event handlers (connection, messages, reactions).
252→   */
253→  private setupEventHandlers(): void {
254→    // QR Code for authentication
255→    this.client.on('qr', (qr: string) => {
256→      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qr)}`;
257→
258→      // Update status API
259→      updateStatus({
260→        state: 'qr_pending',
261→        qrCode: qr,
262→        qrUrl: qrUrl
263→      });
264→
265→      // Console output - show URL only (QR too large for terminal)
266→      console.log('');
267→      console.log('╔══════════════════════════════════════════════════╗');
268→      console.log('║  📱 WhatsApp Authentication Required              ║');
269→      console.log('╚══════════════════════════════════════════════════╝');
270→      console.log('');
271→      console.log('  Open this URL to see QR code:');
272→      console.log(`  ${qrUrl}`);
273→      console.log('');
274→      console.log('  📲 WhatsApp → Settings → Linked Devices → Link');
275→      console.log('');
276→    });
277→
278→    // Ready event
279→    this.client.on('ready', () => {
280→      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });
281→
282→      // Reset reconnection state on successful connection
283→      if (this.isReconnecting) {
284→        logger.success(`WhatsApp reconnected after ${this.reconnectAttempts} attempt(s)`);
285→      }
286→      this.reconnectAttempts = 0;
287→      this.isReconnecting = false;
288→      this.isReady = true;
289→      this.readyAt = Date.now();
290→
291→      logger.section('🐕 Fetch is Ready!');
292→      logger.success('WhatsApp connected and listening for commands');
293→      logger.info('Send a message starting with @fetch to interact');
294→      logger.divider();
295→    });
296→
297→    // Authentication success
298→    this.client.on('authenticated', () => {
299→      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });
300→      logger.success('WhatsApp authentication successful');
301→    });
302→
303→    // Authentication failure
304→    this.client.on('auth_failure', (msg: string) => {
305→      updateStatus({ state: 'error', lastError: msg });
306→      logger.error('WhatsApp authentication failed', msg);
307→    });
308→
309→    // Disconnected — attempt reconnection with exponential backoff
310→    this.client.on('disconnected', (reason: string) => {
311→      updateStatus({ state: 'disconnected', lastError: reason });
312→      logger.warn('WhatsApp disconnected', reason);
313→
314→      // Attempt reconnection unless intentionally destroyed
315→      if (!this.destroyed) {
316→        if (this.shouldPauseAutoReconnect(reason)) {
317→          if (this.reconnectTimer) {
318→            clearTimeout(this.reconnectTimer);
319→            this.reconnectTimer = null;
320→          }
321→          this.isReconnecting = false;
322→          this.reconnectAttempts = 0;
323→          logger.warn(
324→            'Auto-reconnect paused after QR retry exhaustion; waiting for manual restart/setup',
325→          );
326→          return;
327→        }
328→        this.reconnect();
329→      }
330→    });
331→
332→    // ==========================================================================
333→    // MESSAGE REACTION HANDLER
334→    // Emoji reactions like 👍, ❤️, etc. on messages
335→    // ==========================================================================
336→    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js has no typed Reaction export
337→    this.client.on('message_reaction', async (reaction: any) => {
338→      try {
339→        // 1. Skip if bridge not fully ready (prevents startup sync spam)
340→        if (!this.isReady) return;
341→        if (Date.now() - this.readyAt < this.reactionWarmupMs) {
342→          logger.debug('Skipped reaction during startup warmup');
343→          return;
344→        }
345→
346→        // 2. Only process reactions from owner or trusted whitelist members
347→        const senderId = reaction.senderId;
348→        if (!senderId || !this.securityGate.isAuthorizedUser(senderId)) {
349→          // Log only at debug level to keep the main logs clean
350→          logger.debug(`Skipped unauthorized reaction from: ${senderId}`);
351→          return;
352→        }
353→
354→        // 3. Only process reactions on our messages (fromMe)
355→        const msgId = reaction.msgId;
356→        if (!msgId) return;
357→
358→        const emoji = reaction.reaction;
359→        const serializedMsgId = msgId._serialized || String(msgId);
360→        const dedupKey = `${senderId}:${serializedMsgId}:${emoji}`;
361→        const now = Date.now();
362→        const lastSeen = this.reactionDedup.get(dedupKey);
363→        if (lastSeen && (now - lastSeen) < this.reactionDedupTtlMs) {
364→          logger.debug(`Skipped duplicate reaction: ${dedupKey}`);
365→          return;
366→        }
367→        this.reactionDedup.set(dedupKey, now);
368→        for (const [k, ts] of this.reactionDedup) {
369→          if ((now - ts) > this.reactionDedupTtlMs) this.reactionDedup.delete(k);
370→        }
371→
372→        logger.info(`Reaction received: ${emoji} from authorized user on message ${serializedMsgId}`);
373→
374→        // Map reactions to actions
375→        // 👍 = approve/continue, 👎 = cancel/reject, ❌ = cancel
376→        const approveEmojis = ['👍', '✅', '👌', '🙌', '💯'];
377→        const rejectEmojis = ['👎', '❌', '🚫', '⛔'];
378→        const cancelEmojis = ['🛑', '⏹️', '❌'];
379→        const taskManager = await getTaskManager();
380→        const currentTask = taskManager.getCurrentTask();
381→        const awaitingInput = currentTask?.status === 'waiting_input';
382→
383→        if (!awaitingInput) {
384→          logger.debug('Ignored reaction approval: no task awaiting input');
385→          return;
386→        }
387→
388→        if (approveEmojis.includes(emoji)) {
389→          logger.info('Processing approval via reaction');
390→          const responses = await handleMessage(senderId, 'yes');
391→          for (const response of responses) {
392→            await this.client.sendMessage(senderId, response);
393→          }
394→        } else if (rejectEmojis.includes(emoji) || cancelEmojis.includes(emoji)) {
395→          logger.info('Processing rejection/cancel via reaction');
396→          const responses = await handleMessage(senderId, 'no');
397→          for (const response of responses) {
398→            await this.client.sendMessage(senderId, response);
399→          }
400→        }
401→        // Other emojis are ignored (just acknowledgements)
402→      } catch (error) {
403→        logger.error('Failed to process reaction', error);
404→      }
405→    });
406→
407→    // ==========================================================================
408→    // MESSAGE HANDLERS
409→    // ==========================================================================
410→
411→    // Use message_create to catch ALL messages including self-chat
412→    this.client.on('message_create', async (message: Message) => {
413→      // DEDUPLICATION: WhatsApp fires message_create multiple times for same message
414→      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.id not in type defs
415→      const msgId = (message as any).id?._serialized || (message as any).id?.id || String(message.timestamp);
416→      if (!this.deduplicator.isNew(msgId)) {
417→        logger.debug(`Skipped duplicate message: ${msgId}`);
418→        return;
419→      }
420→
421→      logger.debug(`message_create: from=${message.from}, type=${message.type}, fromMe=${message.fromMe}`);
422→
423→      // Handle Voice Notes (PTT)
424→      if (message.type === 'ptt' || message.type === 'audio') {
425→        const success = await this.handleVoiceMessage(message);
426→        if (!success) {
427→          logger.debug('Skipped: voice transcription failed or not available');
428→          return;
429→        }
430→      }
431→
432→      // Handle Images
433→      if (message.type === 'image') {
434→        await this.handleImageMessage(message);
435→        // Note: we don't return if it fails, as it might still have a text caption
436→      }
437→
438→      // Skip empty messages (media without caption, etc.)
439→      if (!message.body || message.body.trim() === '') {
440→        logger.debug('Skipped: empty message body');
441→        return;
442→      }
443→
444→      // Check if this is a reply to a Fetch message (thread continuation)
445→      const isReplyToFetch = message.fromMe ? false : await this.isReplyToFetchMessage(message);
446→      const hasFetchTrigger = message.body.toLowerCase().trim().startsWith('@fetch');
447→
448→      // For messages from us (fromMe=true), ONLY process with explicit @fetch trigger.
449→      // Thread replies are disabled for fromMe to prevent infinite response loops.
450→      if (message.fromMe) {
451→        if (!hasFetchTrigger) {
452→          return;
453→        }
454→        logger.info('Processing self-chat message');
455→      } else {
456→        // For messages from others, allow @fetch trigger OR reply to a Fetch message
457→        if (!hasFetchTrigger && !isReplyToFetch) {
458→          return;
459→        }
460→        logger.info(`Processing incoming message from ${message.from}${isReplyToFetch ? ' (thread reply)' : ''}`);
461→      }
462→
463→      incrementMessageCount();
464→      await this.handleIncomingMessage(message, isReplyToFetch);
465→    });
466→  }
