472→  private trackBotMessage(messageId: string): void {
473→    this.botRecentMessageIds.push(messageId);
474→    if (this.botRecentMessageIds.length > this.maxBotRecentMessages) {
475→      this.botRecentMessageIds.shift(); // Remove oldest
