480→   * Check if message is a reply to a Fetch bot message
481→   */
482→  private async isReplyToFetchMessage(message: Message): Promise<boolean> {
483→    try {
484→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
485→      const quotedMsg = await (message as any).getQuotedMessage();
486→      if (!quotedMsg || !quotedMsg.id || !quotedMsg.id._serialized) return false;
487→
488→      // Check if the quoted message's ID is in our cache of recent bot-sent messages
489→      if (this.botRecentMessageIds.includes(quotedMsg.id._serialized)) {
490→        logger.debug('Message is reply to Fetch response');
491→        return true;
492→      }
493→      return false;
494→    } catch {
495→      return false;
496→    }
