854→  // ===========================================================================
855→
856→  /**
857→   * Recreate and reinitialize the WhatsApp client using exponential backoff.
858→   */
859→  private reconnect(): void {
860→    if (this.destroyed || this.isReconnecting) return;
861→
862→    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
863→      logger.error(
864→        `WhatsApp reconnection failed after ${this.maxReconnectAttempts} attempts — giving up`,
865→      );
866→      updateStatus({ state: 'error', lastError: 'Max reconnection attempts exceeded' });
867→      return;
868→    }
869→
870→    this.isReconnecting = true;
871→    this.reconnectAttempts++;
872→
873→    // Exponential backoff with configurable base, cap, and jitter
874→    const BASE_DELAY = pipeline.reconnectBaseDelay;
875→    const MAX_DELAY = pipeline.reconnectMaxDelay;
876→    const jitter = Math.random() * pipeline.reconnectJitter;
877→    const delay =
878→      Math.min(BASE_DELAY * Math.pow(2, this.reconnectAttempts - 1), MAX_DELAY) + jitter;
879→
880→    logger.info(
881→      `🔄 Reconnecting in ${(delay / 1000).toFixed(1)}s ` +
882→      `(attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})…`,
883→    );
884→
885→    this.reconnectTimer = setTimeout(async () => {
886→      this.reconnectTimer = null;
887→
888→      try {
889→        // Destroy the old client cleanly
890→        try { await this.client.destroy(); } catch { /* already dead */ }
891→
892→        // Fresh Client instance — wweb can't re-initialize the same one
893→        this.client = new Client({
894→          authStrategy: new LocalAuth({
895→            dataPath: '/app/data/.wwebjs_auth',
896→          }),
897→          qrMaxRetries: 10,
898→          puppeteer: {
899→            headless: true,
900→            args: [
901→              '--no-sandbox',
902→              '--disable-setuid-sandbox',
903→              '--disable-dev-shm-usage',
904→              '--disable-accelerated-2d-canvas',
905→              '--no-first-run',
906→              '--no-zygote',
907→              '--disable-gpu',
908→            ],
909→          },
910→        });
911→
912→        // Re-bind event handlers on the new client
913→        // (Task progress listeners reference `this.client` via `this`, so they
914→        //  already point at the new instance — no need to re-register.)
915→        this.setupEventHandlers();
916→        cleanupChromeLocks('/app/data/.wwebjs_auth');
917→
918→        await this.client.initialize();
919→        // On success the 'ready' handler resets reconnect state
920→      } catch (error) {
921→        const msg = error instanceof Error ? error.message : String(error);
922→        logger.error(`Reconnection attempt ${this.reconnectAttempts} failed: ${msg}`);
923→        this.isReconnecting = false;
924→
925→        // Schedule next attempt
926→        this.reconnect();
927→      }
928→    }, delay);
929→  }
930→
931→  // ===========================================================================
932→  // LIFECYCLE
933→  // ===========================================================================
934→
935→  /**
936→   * Stop bridge processing and destroy the WhatsApp client instance.
937→   */
938→  async destroy(): Promise<void> {
939→    this.destroyed = true;
940→
941→    // Cancel any pending reconnection
942→    if (this.reconnectTimer) {
943→      clearTimeout(this.reconnectTimer);
944→      this.reconnectTimer = null;
945→    }
946→
947→    this.rateLimiter.shutdown();
948→    await this.securityGate.shutdown();
949→    await shutdown();
950→    await this.client.destroy();
951→  }
952→}
