/**
 * @fileoverview WhatsApp transport adapter for the Fetch bridge.
 *
 * Responsibilities:
 * - manage WhatsApp Web client lifecycle (auth, ready, disconnect, reconnect)
 * - route inbound messages/reactions through security + handler pipeline
 * - normalize transport edge cases (duplicate events, self-chat, media payloads)
 * - send proactive task progress/question updates back to users
 *
 * @module bridge/client
 * @see {@link Bridge} Runtime bridge class
 */

import pkg from 'whatsapp-web.js';
const { Client, LocalAuth } = pkg;
type Message = pkg.Message;
type ClientType = InstanceType<typeof Client>;
import { logger } from '../utils/logger.js';
import { pipeline } from '../config/pipeline.js';
import { SecurityGate, RateLimiter, validateInput } from '../security/index.js';
import { handleMessage, initializeHandler, shutdown, registerWhatsAppSender } from '../handler/index.js';
import { getTaskIntegration } from '../task/integration.js';
import { getTaskManager } from '../task/manager.js';
import { updateStatus, incrementMessageCount } from '../api/status.js';
import { transcribeAudio, isTranscriptionAvailable } from '../transcription/index.js';
import { analyzeImage, isVisionAvailable } from '../vision/index.js';
import { composeTaskFileOpMessages, composeTaskProgressMessages, composeTaskQuestionMessages } from './progress-message.js';
import * as fs from 'fs';
import * as path from 'path';

// =============================================================================
// TASK EVENT INTERFACES
// =============================================================================

/** Payload shape for task:progress events */
interface TaskProgressEvent {
  sessionId?: string;
  message?: string;
}

/** Payload shape for task:file_op events */
interface TaskFileOpEvent {
  sessionId?: string;
  operation?: string;
  path?: string;
}

/** Payload shape for task:question events */
interface TaskQuestionEvent {
  sessionId?: string;
  question?: string;
}

// =============================================================================
// CHROME LOCK CLEANUP
// =============================================================================

/**
 * Remove stale Chromium singleton lock files under WhatsApp auth data.
 *
 * This runs before client init/re-init to avoid Chromium startup failures
 * after unclean shutdowns.
 *
 * @param authPath - Path to the .wwebjs_auth directory
 */
function cleanupChromeLocks(authPath: string): void {
  const lockNames = new Set(['SingletonLock', 'SingletonCookie', 'SingletonSocket']);

  try {
    if (!fs.existsSync(authPath)) {
      return; // No auth directory yet, nothing to clean
    }

    // Find session directories (session / session-* folders)
    const topEntries = fs.readdirSync(authPath, { withFileTypes: true });

    for (const entry of topEntries) {
      if (!entry.isDirectory() || !entry.name.startsWith('session')) continue;

      const sessionPath = path.join(authPath, entry.name);

      // Directories to scan: the session root and its Default/ subfolder
      const dirsToScan = [sessionPath];
      const defaultPath = path.join(sessionPath, 'Default');
      try { if (fs.statSync(defaultPath).isDirectory()) dirsToScan.push(defaultPath); } catch { /* no Default dir */ }

      for (const dir of dirsToScan) {
        // readdirSync lists ALL directory entries including broken symlinks
        let entries: string[];
        try { entries = fs.readdirSync(dir); } catch { continue; }

        for (const name of entries) {
          if (!lockNames.has(name)) continue;
          const lockPath = path.join(dir, name);
          try {
            fs.unlinkSync(lockPath);
            logger.info(`🧹 Cleaned up stale Chrome lock: ${dir}/${name}`);
          } catch (e) {
            logger.warn(`Could not remove lock ${lockPath}: ${e}`);
          }
        }
      }
    }
  } catch (error) {
    logger.warn(`Could not clean Chrome locks: ${error}`);
  }
}

// =============================================================================
// MESSAGE DEDUPLICATION
// =============================================================================

/**
 * Deduplicate inbound `message_create` events by message id with TTL eviction.
 */
class MessageDeduplicator {
  private processedMessages = new Map<string, number>();
  private readonly TTL_MS = pipeline.deduplicationTtl;
  private cleanupTimer: ReturnType<typeof setInterval>;

  constructor() {
    // Sweep every TTL interval instead of per-message
    this.cleanupTimer = setInterval(() => this.evict(), this.TTL_MS);
    this.cleanupTimer.unref();
  }

  /**
   * Mark and check message id.
   *
   * @returns `true` if message id was not seen in the current TTL window
   */
  isNew(messageId: string): boolean {
    if (this.processedMessages.has(messageId)) {
      return false;
    }
    this.processedMessages.set(messageId, Date.now());
    return true;
  }

  /** Remove cached ids older than TTL. */
  private evict(): void {
    const cutoff = Date.now() - this.TTL_MS;
    for (const [id, ts] of this.processedMessages) {
      if (ts <= cutoff) this.processedMessages.delete(id);
    }
  }
}

// =============================================================================
// BRIDGE CLASS
// =============================================================================

/**
 * Runtime wrapper around `whatsapp-web.js` client.
 *
 * Owns client lifecycle, event wiring, inbound security checks, and outbound
 * proactive messaging integration.
 */
export class Bridge {
  private client: ClientType;
  private securityGate: SecurityGate;
  private rateLimiter: RateLimiter;
  private deduplicator = new MessageDeduplicator();
  private reactionDedup = new Map<string, number>();
  private botRecentMessageIds: string[] = []; // LRU cache for bot sent messages
  private readonly maxBotRecentMessages = 1000;
  private isReady = false;
  private readyAt = 0;
  private readonly reactionWarmupMs = 60_000;
  private readonly reactionDedupTtlMs = 10_000;

  // Reconnection state
  private reconnectAttempts = 0;
  private readonly maxReconnectAttempts = pipeline.maxReconnectAttempts;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private isReconnecting = false;
  private destroyed = false;

  /**
   * Disconnection reasons that should not trigger automatic reconnect loops.
   *
   * QR retry exhaustion is an operator-driven state (no scan happened), not a
   * transient transport failure. Auto-retrying immediately just recreates QR
   * churn and reaches the same terminal reason again.
   */
  private shouldPauseAutoReconnect(reason: string): boolean {
    const normalized = reason.toLowerCase();
    return normalized.includes('max qrcode retries reached');
  }

  constructor() {
    this.client = new Client({
      authStrategy: new LocalAuth({
        dataPath: '/app/data/.wwebjs_auth'
      }),
      // QR code settings - refresh every 20 seconds (default is 45)
      qrMaxRetries: 10,
      puppeteer: {
        headless: true,
        args: [
          '--no-sandbox',
          '--disable-setuid-sandbox',
          '--disable-dev-shm-usage',
          '--disable-accelerated-2d-canvas',
          '--no-first-run',
          '--no-zygote',
          '--disable-gpu'
        ]
      }
    });

    // SecurityGate initialized in initialize() for async whitelist loading
    this.securityGate = null as unknown as SecurityGate;
    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
  }

  /**
   * Initialize security, handler integrations, event listeners, and WhatsApp client.
   */
  async initialize(): Promise<void> {
    // Clean up any stale Chrome lock files from previous crashes
    cleanupChromeLocks('/app/data/.wwebjs_auth');

    // Initialize security gate with Zero Trust Bonding whitelist
    this.securityGate = await SecurityGate.create();

    // Initialize agentic handler
    await initializeHandler();

    // Register WhatsApp sender for proactive messages (task completions, etc.)
    registerWhatsAppSender(async (userId: string, text: string) => {
      try {
        logger.info(`Sending proactive message to ${userId}`);
        const targetId = userId.includes('@') ? userId : `${userId}@c.us`;
        const sentMsg = await this.client.sendMessage(targetId, text);
        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
          this.trackBotMessage(sentMsg.id._serialized);
        }
        logger.success(`Proactive message sent to ${targetId}`);
      } catch (err) {
        logger.error(`Failed to send proactive WhatsApp message to ${userId}`, err);
      }
    });

    this.setupEventHandlers();
    this.setupTaskProgressListeners();
    await this.client.initialize();
  }

  /**
   * Register WhatsApp client event handlers (connection, messages, reactions).
   */
  private setupEventHandlers(): void {
    // QR Code for authentication
    this.client.on('qr', (qr: string) => {
      const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qr)}`;

      // Update status API
      updateStatus({
        state: 'qr_pending',
        qrCode: qr,
        qrUrl: qrUrl
      });

      // Console output - show URL only (QR too large for terminal)
      console.log('');
      console.log('╔══════════════════════════════════════════════════╗');
      console.log('║  📱 WhatsApp Authentication Required              ║');
      console.log('╚══════════════════════════════════════════════════╝');
      console.log('');
      console.log('  Open this URL to see QR code:');
      console.log(`  ${qrUrl}`);
      console.log('');
      console.log('  📲 WhatsApp → Settings → Linked Devices → Link');
      console.log('');
    });

    // Ready event
    this.client.on('ready', () => {
      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });

      // Reset reconnection state on successful connection
      if (this.isReconnecting) {
        logger.success(`WhatsApp reconnected after ${this.reconnectAttempts} attempt(s)`);
      }
      this.reconnectAttempts = 0;
      this.isReconnecting = false;
      this.isReady = true;
      this.readyAt = Date.now();

      logger.section('🐕 Fetch is Ready!');
      logger.success('WhatsApp connected and listening for commands');
      logger.info('Send a message starting with @fetch to interact');
      logger.divider();
    });

    // Authentication success
    this.client.on('authenticated', () => {
      updateStatus({ state: 'authenticated', qrCode: null, qrUrl: null });
      logger.success('WhatsApp authentication successful');
    });

    // Authentication failure
    this.client.on('auth_failure', (msg: string) => {
      updateStatus({ state: 'error', lastError: msg });
      logger.error('WhatsApp authentication failed', msg);
    });

    // Disconnected — attempt reconnection with exponential backoff
    this.client.on('disconnected', (reason: string) => {
      updateStatus({ state: 'disconnected', lastError: reason });
      logger.warn('WhatsApp disconnected', reason);

      // Attempt reconnection unless intentionally destroyed
      if (!this.destroyed) {
        if (this.shouldPauseAutoReconnect(reason)) {
          if (this.reconnectTimer) {
            clearTimeout(this.reconnectTimer);
            this.reconnectTimer = null;
          }
          this.isReconnecting = false;
          this.reconnectAttempts = 0;
          logger.warn(
            'Auto-reconnect paused after QR retry exhaustion; waiting for manual restart/setup',
          );
          return;
        }
        this.reconnect();
      }
    });

    // ==========================================================================
    // MESSAGE REACTION HANDLER
    // Emoji reactions like 👍, ❤️, etc. on messages
    // ==========================================================================
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js has no typed Reaction export
    this.client.on('message_reaction', async (reaction: any) => {
      try {
        // 1. Skip if bridge not fully ready (prevents startup sync spam)
        if (!this.isReady) return;
        if (Date.now() - this.readyAt < this.reactionWarmupMs) {
          logger.debug('Skipped reaction during startup warmup');
          return;
        }

        // 2. Only process reactions from owner or trusted whitelist members
        const senderId = reaction.senderId;
        if (!senderId || !this.securityGate.isAuthorizedUser(senderId)) {
          // Log only at debug level to keep the main logs clean
          logger.debug(`Skipped unauthorized reaction from: ${senderId}`);
          return;
        }

        // 3. Only process reactions on our messages (fromMe)
        const msgId = reaction.msgId;
        if (!msgId) return;

        const emoji = reaction.reaction;
        const serializedMsgId = msgId._serialized || String(msgId);
        const dedupKey = `${senderId}:${serializedMsgId}:${emoji}`;
        const now = Date.now();
        const lastSeen = this.reactionDedup.get(dedupKey);
        if (lastSeen && (now - lastSeen) < this.reactionDedupTtlMs) {
          logger.debug(`Skipped duplicate reaction: ${dedupKey}`);
          return;
        }
        this.reactionDedup.set(dedupKey, now);
        for (const [k, ts] of this.reactionDedup) {
          if ((now - ts) > this.reactionDedupTtlMs) this.reactionDedup.delete(k);
        }

        logger.info(`Reaction received: ${emoji} from authorized user on message ${serializedMsgId}`);

        // Map reactions to actions
        // 👍 = approve/continue, 👎 = cancel/reject, ❌ = cancel
        const approveEmojis = ['👍', '✅', '👌', '🙌', '💯'];
        const rejectEmojis = ['👎', '❌', '🚫', '⛔'];
        const cancelEmojis = ['🛑', '⏹️', '❌'];
        const taskManager = await getTaskManager();
        const currentTask = taskManager.getCurrentTask();
        const awaitingInput = currentTask?.status === 'waiting_input';

        if (!awaitingInput) {
          logger.debug('Ignored reaction approval: no task awaiting input');
          return;
        }

        if (approveEmojis.includes(emoji)) {
          logger.info('Processing approval via reaction');
          const responses = await handleMessage(senderId, 'yes');
          for (const response of responses) {
            await this.client.sendMessage(senderId, response);
          }
        } else if (rejectEmojis.includes(emoji) || cancelEmojis.includes(emoji)) {
          logger.info('Processing rejection/cancel via reaction');
          const responses = await handleMessage(senderId, 'no');
          for (const response of responses) {
            await this.client.sendMessage(senderId, response);
          }
        }
        // Other emojis are ignored (just acknowledgements)
      } catch (error) {
        logger.error('Failed to process reaction', error);
      }
    });

    // ==========================================================================
    // MESSAGE HANDLERS
    // ==========================================================================

    // Use message_create to catch ALL messages including self-chat
    this.client.on('message_create', async (message: Message) => {
      // DEDUPLICATION: WhatsApp fires message_create multiple times for same message
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.id not in type defs
      const msgId = (message as any).id?._serialized || (message as any).id?.id || String(message.timestamp);
      if (!this.deduplicator.isNew(msgId)) {
        logger.debug(`Skipped duplicate message: ${msgId}`);
        return;
      }

      logger.debug(`message_create: from=${message.from}, type=${message.type}, fromMe=${message.fromMe}`);

      // Handle Voice Notes (PTT)
      if (message.type === 'ptt' || message.type === 'audio') {
        const success = await this.handleVoiceMessage(message);
        if (!success) {
          logger.debug('Skipped: voice transcription failed or not available');
          return;
        }
      }

      // Handle Images
      if (message.type === 'image') {
        await this.handleImageMessage(message);
        // Note: we don't return if it fails, as it might still have a text caption
      }

      // Skip empty messages (media without caption, etc.)
      if (!message.body || message.body.trim() === '') {
        logger.debug('Skipped: empty message body');
        return;
      }

      // Check if this is a reply to a Fetch message (thread continuation)
      const isReplyToFetch = message.fromMe ? false : await this.isReplyToFetchMessage(message);
      const hasFetchTrigger = message.body.toLowerCase().trim().startsWith('@fetch');

      // For messages from us (fromMe=true), ONLY process with explicit @fetch trigger.
      // Thread replies are disabled for fromMe to prevent infinite response loops.
      if (message.fromMe) {
        if (!hasFetchTrigger) {
          return;
        }
        logger.info('Processing self-chat message');
      } else {
        // For messages from others, allow @fetch trigger OR reply to a Fetch message
        if (!hasFetchTrigger && !isReplyToFetch) {
          return;
        }
        logger.info(`Processing incoming message from ${message.from}${isReplyToFetch ? ' (thread reply)' : ''}`);
      }

      incrementMessageCount();
      await this.handleIncomingMessage(message, isReplyToFetch);
    });
  }

  /**
   * Tracks a message ID sent by the bot to allow thread replies out of the group.
   * Keeps a bounded list of recent IDs.
   */
  private trackBotMessage(messageId: string): void {
    this.botRecentMessageIds.push(messageId);
    if (this.botRecentMessageIds.length > this.maxBotRecentMessages) {
      this.botRecentMessageIds.shift(); // Remove oldest
    }
  }

  /**
   * Check if message is a reply to a Fetch bot message
   */
  private async isReplyToFetchMessage(message: Message): Promise<boolean> {
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const quotedMsg = await (message as any).getQuotedMessage();
      if (!quotedMsg || !quotedMsg.id || !quotedMsg.id._serialized) return false;

      // Check if the quoted message's ID is in our cache of recent bot-sent messages
      if (this.botRecentMessageIds.includes(quotedMsg.id._serialized)) {
        logger.debug('Message is reply to Fetch response');
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  /**
   * Download and analyze image messages, then append analysis to message body.
   *
   * @returns `true` when analysis context was added to the message
   */
  private async handleImageMessage(message: Message): Promise<boolean> {
    if (!isVisionAvailable()) {
      logger.warn('Image received but vision is not configured (missing API key)');
      return false;
    }

    try {
      logger.info('🖼️ Processing image...');

      const media = await message.downloadMedia();
      if (!media || !media.data) {
        logger.error('Failed to download image media');
        return false;
      }

      // If it's not an image, skip
      if (!media.mimetype.startsWith('image/')) {
        return false;
      }

      const originalCaption = message.body || '';
      const analysis = await analyzeImage(media.data, media.mimetype, originalCaption);

      if (!analysis) return false;

      // Update message body to include analysis context
      message.body = `${originalCaption}\n\n[CONTEXT: Image Analysis]\n${analysis}`.trim();

      logger.success('🖼️ Image analysis added to message context');
      return true;
    } catch (error) {
      logger.error('Failed to handle image message', error);
      return false;
    }
  }

  /**
   * Subscribe to task integration events and forward user-facing updates.
   */
  private setupTaskProgressListeners(): void {
    const integration = getTaskIntegration();

    // Mapping to track last progress message per session to avoid noise
    const lastProgressUpdate = new Map<string, number>();
    const THROTTLE_MS = pipeline.progressThrottle; // Minimum time between general progress updates

    // Helper to resolve user ID from session ID
    const resolveTarget = async (sessionId: string): Promise<string | null> => {
      if (!sessionId) return null;
      // If it looks like a JID, use it directly (legacy/direct support)
      if (sessionId.includes('@c.us') || sessionId.includes('@g.us')) return sessionId;

      // Otherwise, resolve via SessionManager
      try {
        const { getSessionManager } = await import('../session/manager.js');
        const manager = await getSessionManager();
        const session = await manager.getSessionById(sessionId);
        return session ? session.userId : null;
      } catch (_err) {
        logger.warn('Failed to resolve session owner', { sessionId });
        return null;
      }
    };

    // Codex emits structured JSONL lifecycle events on stdout. These are
    // useful for internal telemetry but should never be forwarded verbatim
    // to WhatsApp users.
    const isStructuredHarnessEventLine = (raw: string): boolean => {
      const line = raw.trim();
      if (!line.startsWith('{') || !line.endsWith('}')) return false;
      try {
        const parsed = JSON.parse(line) as { type?: unknown; item?: { type?: unknown } };
        const type = typeof parsed.type === 'string' ? parsed.type : '';
        if (
          type.startsWith('thread.') ||
          type.startsWith('turn.') ||
          type.startsWith('item.')
        ) {
          return true;
        }
        const itemType = typeof parsed.item?.type === 'string' ? parsed.item.type : '';
        return itemType === 'command_execution' || itemType === 'reasoning' || itemType === 'file_change';
      } catch {
        return false;
      }
    };

    integration.on('task:progress', async (event: TaskProgressEvent) => {
      const { sessionId, message } = event;
      if (!sessionId || !message) return;
      if (isStructuredHarnessEventLine(message)) return;

      const targetId = await resolveTarget(sessionId);
      if (!targetId) return;

      const now = Date.now();
      const lastUpdate = lastProgressUpdate.get(sessionId) || 0;

      // Always send priority patterns, throttle others
      const isPriority = /starting|done|complete|failed|error|waiting/i.test(message);

      if (isPriority || (now - lastUpdate > THROTTLE_MS)) {
        try {
          const chunks = await composeTaskProgressMessages(message, sessionId);
          for (const chunk of chunks) {
            const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
            if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
              this.trackBotMessage(sentMsg.id._serialized);
            }
          }
          lastProgressUpdate.set(sessionId, now);
        } catch (error) {
          logger.error('Failed to send progress message', error);
        }
      }
    });

    integration.on('task:file_op', async (event: TaskFileOpEvent) => {
      const { sessionId, operation, path } = event;
      if (!sessionId || !operation || !path) return;

      const targetId = await resolveTarget(sessionId);
      if (!targetId) return;

      try {
        const chunks = composeTaskFileOpMessages(operation, path);
        for (const chunk of chunks) {
          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
            this.trackBotMessage(sentMsg.id._serialized);
          }
        }
      } catch (error) {
        logger.error('Failed to send file_op message', error);
      }
    });

    integration.on('task:question', async (event: TaskQuestionEvent) => {
      const { sessionId, question } = event;
      if (!sessionId || !question) return;

      const targetId = await resolveTarget(sessionId);
      if (!targetId) return;

      try {
        const chunks = composeTaskQuestionMessages(question);
        for (const chunk of chunks) {
          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
            this.trackBotMessage(sentMsg.id._serialized);
          }
        }
      } catch (error) {
        logger.error('Failed to send task question', error);
      }
    });
  }

  /**
   * Transcribe incoming voice notes and replace message body with transcript.
   *
   * @returns `true` when transcription succeeded and body was updated
   */
  private async handleVoiceMessage(message: Message): Promise<boolean> {
    if (!isTranscriptionAvailable()) {
      logger.warn('Voice message received but transcription is not configured (missing API key)');
      return false;
    }

    try {
      logger.info('🎤 Processing voice note...');

      const media = await message.downloadMedia();

      const buffer = Buffer.from(media.data, 'base64');
      const filename = media.filename || `voice-${Date.now()}.ogg`;

      const result = await transcribeAudio(buffer, filename);
      const transcription = result.text;

      if (!transcription || transcription.trim().length === 0) {
        logger.warn('Transcription returned empty text');
        return false;
      }

      // Prepend a microphone emoji to indicate it was a voice note
      // and inject into the message body for normal processing
      message.body = transcription;

      logger.success(`🎤 Transcribed voice (${result.language || 'unknown'}): "${transcription}"`);
      return true;
    } catch (error) {
      logger.error('Failed to handle voice message', error);
      return false;
    }
  }

  /**
   * Process one inbound message through auth, rate limiting, validation, and handler execution.
   */
  private async handleIncomingMessage(message: Message, isThreadReply: boolean = false): Promise<void> {
    const senderId = message.from;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.author not in type defs
    const participantId = (message as any).author; // Group message author
    const messageBody = message.body;

    // SECURITY GATE 1: Validate authorization
    // For thread replies, we skip the @fetch trigger check but still verify identity
    if (isThreadReply) {
      // For thread replies, verify owner OR trusted whitelist member (no @fetch required)
      const isGroup = senderId.endsWith('@g.us');
      const checkId = isGroup ? participantId : senderId;
      if (!checkId) return;
      if (!this.securityGate.isOwnerMessage(senderId, participantId) &&
        !this.securityGate.getWhitelist()?.has(checkId.replace(/@(c|g|s)\.us$/, '').replace(/\D/g, '') || '')) {
        return;
      }
    } else {
      // Normal flow: require @fetch trigger + (owner OR trusted)
      if (!this.securityGate.isAuthorized(senderId, participantId, messageBody)) {
        return;
      }
    }

    // Strip the @fetch trigger from the message (if present)
    const command = this.securityGate.stripTrigger(messageBody);

    // SECURITY GATE 2: Rate limiting
    const rateLimitId = participantId || senderId;
    const sessionUserId = await this.resolveCanonicalSessionUserId(message, senderId, participantId);
    if (!(await this.rateLimiter.isAllowed(rateLimitId))) {
      await message.reply('⏳ Slow down! You\'re sending too many requests. Please wait a moment.');
      return;
    }

    // SECURITY GATE 3: Input validation
    const validation = validateInput(command);
    if (!validation.valid) {
      logger.warn(`Invalid input from owner: ${validation.error}`);
      await message.reply(`❌ ${validation.error}`);
      return;
    }

    logger.message(`Received: "${validation.sanitized.substring(0, 40)}${validation.sanitized.length > 40 ? '...' : ''}"`);

    try {
      let firstMessageSent = false;

      // Determine prefix for different media types
      let mediaPrefix = '';
      if (message.type === 'ptt' || message.type === 'audio') {
        mediaPrefix = `🎤 I heard: "${validation.sanitized}"\n\n`;
      } else if (message.type === 'image') {
        mediaPrefix = `🖼️ I see an image!\n\n`;
        // Optional: you could extract the summary from the analysis here if desired
      }

      // Process through agentic handler
      const responses = await handleMessage(
        sessionUserId,
        validation.sanitized,
        async (text) => {
          let output = text;
          if (!firstMessageSent && mediaPrefix) {
            output = mediaPrefix + output;
            firstMessageSent = true;
          }
          const sentMsg = await message.reply(output);
          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
            this.trackBotMessage(sentMsg.id._serialized);
          }
        }
      );

      // Send all response messages
      for (let i = 0; i < responses.length; i++) {
        let response = responses[i];

        // Prepend media info prefix if it was a voice note or image and we haven't sent the prefix yet
        if (!firstMessageSent && mediaPrefix) {
          response = mediaPrefix + response;
          firstMessageSent = true; // Mark as sent so subsequent responses don't get it
        }

        const sentMsg = await message.reply(response);
        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
          this.trackBotMessage(sentMsg.id._serialized);
        }
        logger.success(`Reply sent (${response.length} chars)`);

        // Small delay between messages to avoid rate limiting
        if (responses.length > 1 && i < responses.length - 1) {
          await new Promise(resolve => setTimeout(resolve, 500));
        }
      }
    } catch (error) {
      logger.error('Failed to process message', error);
      await message.reply('❌ Sorry, I encountered an error processing your request.');
    }
  }

  /**
   * Resolve a stable per-user session identifier.
   *
   * Prefer phone-number JIDs (e.g. `15551234567@c.us`) so sessions don't bind
   * to opaque WhatsApp LID identifiers (`...@lid`) when a number is available.
   */
  private async resolveCanonicalSessionUserId(
    message: Message,
    senderId: string,
    participantId: string | undefined,
  ): Promise<string> {
    const isGroup = senderId.endsWith('@g.us');
    const baseId = (isGroup ? (participantId || senderId) : senderId) || senderId;

    // Already canonical.
    if (baseId.endsWith('@c.us')) {
      return baseId;
    }

    try {
      const contact = await message.getContact();
      // whatsapp-web.js commonly exposes `number` and `id._serialized`.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- runtime shape varies by WA account mode
      const contactAny = contact as any;
      const number = String(contactAny?.number || '').replace(/\D/g, '');
      if (number.length >= 10 && number.length <= 15) {
        return `${number}@c.us`;
      }

      const serialized = String(contactAny?.id?._serialized || '');
      if (serialized.endsWith('@c.us')) {
        return serialized;
      }
    } catch {
      // Ignore contact lookup failures and continue with fallback normalization.
    }

    const atIndex = baseId.indexOf('@');
    const local = atIndex >= 0 ? baseId.slice(0, atIndex) : baseId;
    const digits = local.replace(/\D/g, '');
    if (digits.length >= 10 && digits.length <= 15) {
      return `${digits}@c.us`;
    }

    return baseId;
  }

  // ===========================================================================
  // RECONNECTION
  // ===========================================================================

  /**
   * Recreate and reinitialize the WhatsApp client using exponential backoff.
   */
  private reconnect(): void {
    if (this.destroyed || this.isReconnecting) return;

    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      logger.error(
        `WhatsApp reconnection failed after ${this.maxReconnectAttempts} attempts — giving up`,
      );
      updateStatus({ state: 'error', lastError: 'Max reconnection attempts exceeded' });
      return;
    }

    this.isReconnecting = true;
    this.reconnectAttempts++;

    // Exponential backoff with configurable base, cap, and jitter
    const BASE_DELAY = pipeline.reconnectBaseDelay;
    const MAX_DELAY = pipeline.reconnectMaxDelay;
    const jitter = Math.random() * pipeline.reconnectJitter;
    const delay =
      Math.min(BASE_DELAY * Math.pow(2, this.reconnectAttempts - 1), MAX_DELAY) + jitter;

    logger.info(
      `🔄 Reconnecting in ${(delay / 1000).toFixed(1)}s ` +
      `(attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})…`,
    );

    this.reconnectTimer = setTimeout(async () => {
      this.reconnectTimer = null;

      try {
        // Destroy the old client cleanly
        try { await this.client.destroy(); } catch { /* already dead */ }

        // Fresh Client instance — wweb can't re-initialize the same one
        this.client = new Client({
          authStrategy: new LocalAuth({
            dataPath: '/app/data/.wwebjs_auth',
          }),
          qrMaxRetries: 10,
          puppeteer: {
            headless: true,
            args: [
              '--no-sandbox',
              '--disable-setuid-sandbox',
              '--disable-dev-shm-usage',
              '--disable-accelerated-2d-canvas',
              '--no-first-run',
              '--no-zygote',
              '--disable-gpu',
            ],
          },
        });

        // Re-bind event handlers on the new client
        // (Task progress listeners reference `this.client` via `this`, so they
        //  already point at the new instance — no need to re-register.)
        this.setupEventHandlers();
        cleanupChromeLocks('/app/data/.wwebjs_auth');

        await this.client.initialize();
        // On success the 'ready' handler resets reconnect state
      } catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        logger.error(`Reconnection attempt ${this.reconnectAttempts} failed: ${msg}`);
        this.isReconnecting = false;

        // Schedule next attempt
        this.reconnect();
      }
    }, delay);
  }

  // ===========================================================================
  // LIFECYCLE
  // ===========================================================================

  /**
   * Stop bridge processing and destroy the WhatsApp client instance.
   */
  async destroy(): Promise<void> {
    this.destroyed = true;

    // Cancel any pending reconnection
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }

    this.rateLimiter.shutdown();
    await this.securityGate.shutdown();
    await shutdown();
    await this.client.destroy();
  }
}

