  1→/**
  2→ * @fileoverview Handles inbound WhatsApp messages and task event notifications.
  3→ *
  4→ * Responsibilities:
  5→ * - initialize session/task integrations
  6→ * - route deterministic slash commands
  7→ * - delegate regular messages to agent core
  8→ * - format and return WhatsApp-ready replies
  9→ * - push proactive task notifications via registered sender
 10→ *
 11→ * @module handler
 12→ */
 13→
 14→import { SessionManager, getSessionManager } from '../session/manager.js';
 15→import { processMessage, selectPromptMode, type AgentResponse } from '../agent/core.js';
 16→import { type TaskManager, getTaskManager as getPersistentTaskManager } from '../task/manager.js';
 17→import type { TaskId } from '../task/types.js';
 18→import { formatAndChunkForWhatsApp, formatForWhatsApp } from '../agent/whatsapp-format.js';
 19→import { composeWhatsAppResponse } from '../agent/composer.js';
 20→import { formatNotification } from '../agent/notifications.js';
 21→import type { ResponseEnvelope } from '../agent/envelope.js';
 22→import { logger } from '../utils/logger.js';
 23→
 24→// =============================================================================
 25→// SINGLETON STATE
 26→// =============================================================================
 27→
 28→/** Session manager singleton. */
 29→let sessionManager: SessionManager | null = null;
 30→
 31→/** Task manager singleton. */
 32→let taskManager: TaskManager | null = null;
 33→
 34→/** Guard to prevent duplicate initialization. */
 35→let initialized = false;
 36→
 37→/** Optional sender used for proactive task notifications. */
 38→let sendWhatsApp: ((userId: string, text: string) => Promise<void>) | null = null;
 39→
 40→const BROKEN_CODEX_SKILL_LINK_PATTERN =
 41→  /failed to stat skills entry .*\/root\/\.codex\/skills\/|missing symlink.*\/root\/\.codex\/skills\//i;
 42→
 43→/**
 44→ * Registers a callback used to send proactive WhatsApp messages.
 45→ */
 46→export function registerWhatsAppSender(fn: (userId: string, text: string) => Promise<void>): void {
 47→  sendWhatsApp = fn;
 48→  logger.info('WhatsApp sender registered for proactive messages');
 49→}
 50→
 51→function renderEnvelopeChunks(envelope: ResponseEnvelope, intent?: AgentResponse['intent']): string[] {
 52→  const composed = composeWhatsAppResponse(envelope);
 53→  const chunks = formatAndChunkForWhatsApp(composed, intent);
 54→  return chunks;
 55→}
 56→
 57→async function sendEnvelopeNotification(userId: string, envelope: ResponseEnvelope): Promise<void> {
 58→  if (!sendWhatsApp) return;
 59→  const messages = renderEnvelopeChunks(envelope);
 60→  for (const msg of messages) {
 61→    await sendWhatsApp(userId, msg);
 62→  }
 63→}
 64→
 65→// =============================================================================
 66→// INITIALIZATION
 67→// =============================================================================
 68→
 69→/**
 70→ * Initializes handler dependencies and task event listeners once.
 71→ */
 72→export async function initializeHandler(): Promise<void> {
 73→  if (initialized) return;
 74→
 75→  logger.section('⚙️  Initializing Handler');
 76→
 77→  // Initialize components
 78→  sessionManager = await getSessionManager();
 79→  logger.success('Session manager ready');
 80→  logger.success('Tool registry loaded');
 81→
 82→  taskManager = await getPersistentTaskManager();
 83→  logger.success('Task manager ready');
 84→
 85→  // Log if there's an active task from previous session
 86→  const currentTask = taskManager.getCurrentTask();
 87→  if (currentTask && ['pending', 'running', 'waiting_input'].includes(currentTask.status)) {
 88→    logger.info(`Active task restored from persistence: ${currentTask.id}`);
 89→  }
 90→
 91→  // Initialize task-harness integration
 92→  const { initializeTaskIntegration, getTaskIntegration } = await import('../task/integration.js');
 93→  await initializeTaskIntegration();
 94→  logger.success('Task-harness integration ready');
 95→
 96→  // Subscribe to task events — write to session + notify WhatsApp
 97→  const integration = getTaskIntegration();
 98→
 99→  integration.on('task:started', async ({ sessionId, goal }: { taskId: string; sessionId?: string; goal: string }) => {
100→    if (!sessionId || sessionId === 'unknown') return;
101→
102→    try {
103→      const sManager = sessionManager!;
104→      const session = await sManager.getSessionById(sessionId);
105→
106→      if (!session) return;
107→
108→      // Notify WhatsApp with persona
109→      if (sendWhatsApp) {
110→        const notification = await formatNotification('task:started', {
111→          goal,
112→          scopeKey: session.id,
113→        });
114→        await sendEnvelopeNotification(session.userId, {
115→          kind: 'progress',
116→          severity: 'info',
117→          mode: 'conversational',
118→          emojiLevel: 'normal',
119→          title: 'Task Started',
120→          summary: notification,
121→        });
122→      }
123→    } catch (err) {
124→      logger.error('Failed to handle task:started event', err);
125→    }
126→  });
127→
128→  integration.on('task:completed', async ({ taskId, sessionId }: { taskId: string; sessionId?: string }) => {
129→    if (!sessionId || sessionId === 'unknown') return;
130→
131→    try {
132→      const sManager = sessionManager!;
133→      const session = await sManager.getSessionById(sessionId);
134→
135→      if (!session) {
136→        logger.warn(`Session not found for task completion`, { sessionId });
137→        return;
138→      }
139→
140→      const taskMgr = await getPersistentTaskManager();
141→      const task = taskMgr.getTask(taskId as TaskId);
142→
143→      if (!task) return;
144→
145→      const summary = task.result?.summary ?? 'Task completed';
146→
147→      // Clear active task
148→      session.activeTaskId = null;
149→      await sManager.updateSession(session);
150→
151→      // Build enriched completion message via hybrid notification system
152→      const durationSec = (task.startedAt && task.completedAt)
153→        ? Math.round((new Date(task.completedAt).getTime() - new Date(task.startedAt).getTime()) / 1000)
154→        : undefined;
155→
156→      const notification = await formatNotification('task:completed', {
157→        summary,
158→        filesCreated: task.result?.filesCreated,
159→        filesModified: task.result?.filesModified,
160→        filesDeleted: task.result?.filesDeleted,
161→        durationSec,
162→        scopeKey: session.id,
163→      });
164→      const completedEnvelope: ResponseEnvelope = {
165→        kind: 'action_result',
166→        severity: 'success',
167→        mode: 'conversational',
168→        emojiLevel: 'normal',
169→        title: 'Task Completed',
170→        summary: notification,
171→      };
172→      await sManager.addAssistantMessage(session, composeWhatsAppResponse(completedEnvelope));
173→      if (sendWhatsApp) {
174→        await sendEnvelopeNotification(session.userId, completedEnvelope);
175→      }
176→    } catch (err) {
177→      logger.error('Failed to handle task:completed event', err);
178→    }
179→  });
180→
181→  integration.on('task:failed', async ({ sessionId, error }: { taskId: string; sessionId?: string; error?: string }) => {
182→    if (!sessionId || sessionId === 'unknown') return;
183→
184→    try {
185→      const sManager = sessionManager!;
186→      const session = await sManager.getSessionById(sessionId);
187→
188→      if (!session) {
189→        logger.warn(`Session not found for task failure`, { sessionId });
190→        return;
191→      }
192→
193→      const userFacingError = normalizeTaskFailure(error);
194→
195→      session.activeTaskId = null;
196→      await sManager.updateSession(session);
197→
198→      // Send WhatsApp notification
199→      const notification = await formatNotification('task:failed', {
200→        error: userFacingError,
201→        scopeKey: session.id,
202→      });
203→      const failedEnvelope: ResponseEnvelope = {
204→        kind: 'error',
205→        severity: 'error',
206→        mode: 'conversational',
207→        emojiLevel: 'normal',
208→        title: 'Task Failed',
209→        summary: notification,
210→      };
211→      await sManager.addAssistantMessage(session, composeWhatsAppResponse(failedEnvelope));
212→      if (sendWhatsApp) {
213→        await sendEnvelopeNotification(session.userId, failedEnvelope);
214→      }
215→    } catch (err) {
216→      logger.error('Failed to handle task:failed event', err);
217→    }
218→  });
219→
220→  initialized = true;
221→  logger.divider();
222→}
223→
224→// =============================================================================
225→// MAIN HANDLER
226→// =============================================================================
227→
228→/**
229→ * Processes one incoming WhatsApp message.
230→ *
231→ * @param userId - WhatsApp JID (phone number)
232→ * @param message - Incoming message text
233→ * @param onProgress - Optional callback for intermediate messages
234→ * @returns Array of response messages to send
235→ */
236→export async function handleMessage(
237→  userId: string,
238→  message: string,
239→  onProgress?: (text: string) => Promise<void>
240→): Promise<string[]> {
241→  // Ensure initialized
242→  if (!initialized) {
243→    await initializeHandler();
244→  }
245→
246→  const startTime = Date.now();
247→  logger.info(`Processing message (${message.length} chars)`);
248→
249→  // Validate non-empty message
250→  if (!message || !message.trim()) {
251→    return ['I didn\'t catch that - could you send a message?'];
252→  }
253→
254→  // Type-safety assertions
255→  const sManager = sessionManager!;
256→
257→  try {
258→    // Get or create session
259→    const session = await sManager.getOrCreateSession(userId);
260→
261→    // Update last activity
262→    session.lastActivityAt = new Date().toISOString();
263→    await sManager.updateSession(session);
264→
265→    // Allow deterministic stop/cancel to interrupt an in-flight run.
266→    const lowerMessage = message.trim().toLowerCase();
267→    if (lowerMessage === '/stop' || lowerMessage === '/cancel' || lowerMessage.startsWith('/stop ') || lowerMessage.startsWith('/cancel ')) {
268→      await sManager.cancelAgentRun(session, 'Cancelled by /stop');
269→    }
270→
271→    // Check for commands (slash commands AND natural language triggers like "what can you do")
272→    const { parseCommand } = await import('../commands/parser.js');
273→    const result = await parseCommand(message, session, sManager);
274→    if (result.handled) {
275→      if (result.envelopes?.length) {
276→        const rendered: string[] = [];
277→        for (const envelope of result.envelopes) {
278→          rendered.push(...renderEnvelopeChunks(envelope));
279→        }
280→        return rendered;
281→      }
282→      // Format command responses for WhatsApp too
283→      return (result.responses || []).map(r => formatForWhatsApp(r));
284→    }
285→
286→    const promptMode = selectPromptMode(message);
287→    const runAcquire = await sManager.acquireAgentRun(session, message, promptMode);
288→    if (!runAcquire.acquired) {
289→      return [formatForWhatsApp('I am still working on your previous request. Send /stop to interrupt it first.')];
290→    }
291→
292→    const runId = runAcquire.run.runId;
293→
294→    // Process with agent
295→    // Add a "thinking" message if it takes more than 3 seconds on the first try
296→    let initialSent = false;
297→    let settled = false;
298→    const thinkingTimer = setTimeout(() => {
299→      if (!initialSent && !settled && onProgress) {
300→        import('../agent/core.js').then(({ generateProgressMessage }) => {
301→          return generateProgressMessage(message, 1);
