      }
    }

    // Discord
    if (env.DISCORD_TOKEN) {
      try {
        const { DiscordBridge } = await import('./discord/index.js');
        const allowedRoles = (env.DISCORD_ALLOWED_ROLES as string || '')
          .split(',')
