/**
 * @fileoverview Discord bridge implementation using discord.js.
 *
 * Connects Fetch to Discord servers, supporting:
 * - Channel-based messaging with mention triggers
 * - Thread/reply context
 * - Role-based access control
 * - File attachments
 *
 * @module bridge/discord
 */

import type { MessageBridge, ChannelType } from '../interface.js';
import { logger } from '../../utils/logger.js';
import { RateLimiter, validateInput } from '../../security/index.js';
import { handleMessage, registerChannelSender } from '../../handler/index.js';
import { pipeline } from '../../config/pipeline.js';
import { formatTextForChannel } from '../../agent/channel-format.js';

// =============================================================================
// TYPES
// =============================================================================

/** Minimal discord.js shapes to avoid hard dependency on discord.js types. */
interface DiscordMessage {
  id: string;
  content: string;
  author: { id: string; bot: boolean; username: string };
  channel: {
    id: string;
    type: number;
    send: (content: string) => Promise<{ id: string }>;
    isDMBased: () => boolean;
  };
  guild?: { id: string };
  member?: { roles: { cache: Map<string, { name: string }> } };
  mentions: { has: (user: unknown) => boolean };
  reference?: { messageId: string };
  reply: (content: string) => Promise<{ id: string }>;
}

interface DiscordClient {
  login: (token: string) => Promise<string>;
  destroy: () => Promise<void>;
  on: (event: string, handler: (...args: unknown[]) => void) => void;
  once: (event: string, handler: (...args: unknown[]) => void) => void;
  user?: { id: string; username: string; tag: string };
  channels: {
    fetch: (id: string) => Promise<{ send: (content: string) => Promise<{ id: string }> } | null>;
  };
}

interface DiscordIntents {
  Guilds: number;
  GuildMessages: number;
  MessageContent: number;
  DirectMessages: number;
}

// =============================================================================
// DISCORD BRIDGE
// =============================================================================

export class DiscordBridge implements MessageBridge {
  readonly channel: ChannelType = 'discord';
  private client: DiscordClient | null = null;
  private ready = false;
  private rateLimiter: RateLimiter;
  private botUserId: string | null = null;

  private readonly token: string;
  private readonly allowedRoles: Set<string>;
  private readonly allowedChannels: Set<string>;

  constructor(config: { token: string; allowedRoles?: string[]; allowedChannels?: string[] }) {
    this.token = config.token;
    this.allowedRoles = new Set(config.allowedRoles ?? []);
    this.allowedChannels = new Set(config.allowedChannels ?? []);
    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
  }

  async initialize(): Promise<void> {
    logger.section('🔌 Initializing Discord Bridge');

    try {
      const { Client, GatewayIntentBits } = await import('discord.js');

      this.client = new Client({
        intents: [
          GatewayIntentBits.Guilds,
          GatewayIntentBits.GuildMessages,
          GatewayIntentBits.MessageContent,
          GatewayIntentBits.DirectMessages,
        ],
      }) as unknown as DiscordClient;

      // Register message sender for proactive messages
      registerChannelSender('discord', async (userId: string, text: string) => {
        await this.sendMessage(userId, text);
      });

      this.setupEventHandlers();
      await this.client.login(this.token);

      // ready event will set this.ready = true
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.error(`Failed to initialize Discord Bridge: ${msg}`);
      throw error;
    }
  }

  async destroy(): Promise<void> {
    this.ready = false;
    this.rateLimiter.shutdown();
    if (this.client) {
      await this.client.destroy();
      this.client = null;
    }
    logger.info('Discord Bridge destroyed');
  }

  async sendMessage(target: string, text: string, _options?: Record<string, unknown>): Promise<string | null> {
    if (!this.client) return null;
    try {
      const formatted = formatTextForChannel(text, 'discord');
      const channel = await this.client.channels.fetch(target);
      if (!channel) return null;
      const result = await channel.send(formatted);
      return result.id;
    } catch (error) {
      logger.error('Failed to send Discord message', error);
      return null;
    }
  }

  isReady(): boolean {
    return this.ready;
  }

  // ===========================================================================
  // EVENT HANDLERS
  // ===========================================================================

  private setupEventHandlers(): void {
    if (!this.client) return;

    this.client.once('ready', () => {
      this.ready = true;
      this.botUserId = this.client?.user?.id ?? null;
      logger.success(`Discord Bridge connected as ${this.client?.user?.tag ?? 'unknown'}`);
    });

    this.client.on('messageCreate', async (...args: unknown[]) => {
      const message = args[0] as DiscordMessage;
      await this.handleDiscordMessage(message);
    });
  }

  private async handleDiscordMessage(message: DiscordMessage): Promise<void> {
    // Skip bot messages
    if (message.author.bot) return;

    const senderId = message.author.id;
    const isDM = message.channel.isDMBased();

    // In servers: require bot mention or @fetch trigger
    if (!isDM) {
      const hasMention = this.botUserId ? message.mentions.has({ id: this.botUserId }) : false;
      const hasTrigger = message.content.toLowerCase().startsWith('@fetch');
      if (!hasMention && !hasTrigger) return;

      // Channel allowlist check
      if (this.allowedChannels.size > 0 && !this.allowedChannels.has(message.channel.id)) {
        return;
      }

      // Role-based access check
      if (this.allowedRoles.size > 0 && message.member) {
        const memberRoles = message.member.roles.cache;
        const hasAllowedRole = Array.from(memberRoles.values()).some(
          (role) => this.allowedRoles.has(role.name),
        );
        if (!hasAllowedRole) return;
      }
    }

    // Strip bot mention from message text
    let messageText = message.content;
    if (this.botUserId) {
      messageText = messageText.replace(new RegExp(`<@!?${this.botUserId}>`, 'g'), '').trim();
    }
    messageText = messageText.replace(/^@fetch\s*/i, '').trim();

    if (!messageText) return;

    // Rate limiting
    if (!(await this.rateLimiter.isAllowed(senderId))) {
      await message.reply('Slow down! You\'re sending too many requests. Please wait a moment.');
      return;
    }

    // Input validation
    const validation = validateInput(messageText);
    if (!validation.valid) {
      await message.reply(`Error: ${validation.error}`);
      return;
    }

    try {
      const responses = await handleMessage(
        `discord:${senderId}`,
        validation.sanitized,
        async (text) => {
          const formatted = formatTextForChannel(text, 'discord');
          await message.reply(formatted);
        },
      );

      for (const response of responses) {
        const formatted = formatTextForChannel(response, 'discord');
        // Discord has a 2000 char limit, chunk if needed
        if (formatted.length > 2000) {
          const chunks = chunkText(formatted, 2000);
          for (const chunk of chunks) {
            await message.channel.send(chunk);
          }
        } else {
          await message.reply(formatted);
        }
      }
    } catch (error) {
      logger.error('Failed to process Discord message', error);
      await message.reply('Sorry, I encountered an error processing your request.');
    }
  }
}

// =============================================================================
// HELPERS
// =============================================================================

function chunkText(text: string, maxLen: number): string[] {
  const chunks: string[] = [];
  let remaining = text;
  while (remaining.length > maxLen) {
    let splitAt = remaining.lastIndexOf('\n', maxLen);
    if (splitAt <= 0) splitAt = maxLen;
    chunks.push(remaining.substring(0, splitAt));
    remaining = remaining.substring(splitAt).trimStart();
  }
  if (remaining) chunks.push(remaining);
  return chunks;
}

/**
 * @fileoverview Slack bridge implementation using @slack/bolt.
 *
 * Connects Fetch to Slack workspaces via the Bolt SDK, supporting:
 * - App mentions and direct messages
 * - Thread-based conversations
 * - File uploads
 * - Channel-based context
 *
 * @module bridge/slack
 */

import type { MessageBridge, InboundMessage, ChannelType } from '../interface.js';
import { logger } from '../../utils/logger.js';
import { SecurityGate, RateLimiter, validateInput } from '../../security/index.js';
import { handleMessage, registerChannelSender } from '../../handler/index.js';
import { pipeline } from '../../config/pipeline.js';
import { formatTextForChannel } from '../../agent/channel-format.js';

// =============================================================================
// TYPES
// =============================================================================

/** Minimal Slack event shapes to avoid hard dependency on @slack/bolt types. */
interface SlackMessageEvent {
  type: string;
  text: string;
  user: string;
  channel: string;
  ts: string;
  thread_ts?: string;
  bot_id?: string;
  files?: Array<{ url_private: string; mimetype: string; name: string }>;
}

interface SlackApp {
  start: () => Promise<void>;
  stop: () => Promise<void>;
  event: (eventName: string, handler: (args: { event: SlackMessageEvent; say: SayFn }) => Promise<void>) => void;
  client: {
    chat: {
      postMessage: (args: { channel: string; text: string; thread_ts?: string }) => Promise<{ ts?: string }>;
    };
    files: {
      uploadV2: (args: { channel_id: string; content: string; filename: string; thread_ts?: string }) => Promise<void>;
    };
  };
}

type SayFn = (args: { text: string; thread_ts?: string } | string) => Promise<{ ts?: string }>;

// =============================================================================
// SLACK BRIDGE
// =============================================================================

export class SlackBridge implements MessageBridge {
  readonly channel: ChannelType = 'slack';
  private app: SlackApp | null = null;
  private ready = false;
  private securityGate: SecurityGate | null = null;
  private rateLimiter: RateLimiter;
  private botUserId: string | null = null;

  private readonly botToken: string;
  private readonly appToken: string;
  private readonly signingSecret: string;

  constructor(config: { botToken: string; appToken: string; signingSecret?: string }) {
    this.botToken = config.botToken;
    this.appToken = config.appToken;
    this.signingSecret = config.signingSecret ?? '';
    this.rateLimiter = new RateLimiter(pipeline.rateLimitMax, pipeline.rateLimitWindow);
  }

  async initialize(): Promise<void> {
    logger.section('🔌 Initializing Slack Bridge');

    try {
      // Dynamic import to avoid hard dependency when Slack is not configured
      const { App } = await import('@slack/bolt');

      this.app = new App({
        token: this.botToken,
        appToken: this.appToken,
        socketMode: true,
        ...(this.signingSecret ? { signingSecret: this.signingSecret } : {}),
      }) as unknown as SlackApp;

      this.securityGate = await SecurityGate.create();

      // Register message sender for proactive messages
      registerChannelSender('slack', async (userId: string, text: string) => {
        await this.sendMessage(userId, text);
      });

      this.setupEventHandlers();
      await this.app.start();
      this.ready = true;

      logger.success('Slack Bridge connected and listening');
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      logger.error(`Failed to initialize Slack Bridge: ${msg}`);
      throw error;
    }
  }

  async destroy(): Promise<void> {
    this.ready = false;
    this.rateLimiter.shutdown();
    if (this.securityGate) {
      await this.securityGate.shutdown();
    }
    if (this.app) {
      await this.app.stop();
      this.app = null;
    }
    logger.info('Slack Bridge destroyed');
  }

  async sendMessage(target: string, text: string, options?: Record<string, unknown>): Promise<string | null> {
    if (!this.app) return null;
    try {
      const formatted = formatTextForChannel(text, 'slack');
      const result = await this.app.client.chat.postMessage({
        channel: target,
        text: formatted,
        thread_ts: options?.threadTs as string | undefined,
      });
      return result.ts ?? null;
    } catch (error) {
      logger.error('Failed to send Slack message', error);
      return null;
    }
  }

  isReady(): boolean {
    return this.ready;
  }

  // ===========================================================================
  // EVENT HANDLERS
  // ===========================================================================

  private setupEventHandlers(): void {
    if (!this.app) return;

    // Listen for app_mention events (when someone @mentions the bot)
    this.app.event('app_mention', async ({ event, say }: { event: SlackMessageEvent; say: SayFn }) => {
      await this.handleSlackMessage(event, say);
    });

    // Listen for direct messages
    this.app.event('message', async ({ event, say }: { event: SlackMessageEvent; say: SayFn }) => {
      // Skip bot messages to prevent loops
      if (event.bot_id) return;
      // Only handle DMs (channel type starts with D)
      if (!event.channel.startsWith('D')) return;
      await this.handleSlackMessage(event, say);
    });
  }

  private async handleSlackMessage(event: SlackMessageEvent, say: SayFn): Promise<void> {
    const senderId = event.user;
    if (!senderId) return;

    // Skip messages from the bot itself
    if (this.botUserId && senderId === this.botUserId) return;

    // Strip bot mention from message text
    let messageText = (event.text || '').replace(/<@[A-Z0-9]+>/g, '').trim();
    if (!messageText) return;

    // Rate limiting
    if (!(await this.rateLimiter.isAllowed(senderId))) {
      await say({ text: 'Slow down! You\'re sending too many requests. Please wait a moment.', thread_ts: event.thread_ts || event.ts });
      return;
    }

    // Input validation
    const validation = validateInput(messageText);
    if (!validation.valid) {
      await say({ text: `Error: ${validation.error}`, thread_ts: event.thread_ts || event.ts });
      return;
    }

    const threadTs = event.thread_ts || event.ts;

    try {
      const responses = await handleMessage(
        `slack:${senderId}`,
        validation.sanitized,
        async (text) => {
          const formatted = formatTextForChannel(text, 'slack');
          await say({ text: formatted, thread_ts: threadTs });
        },
      );

      for (const response of responses) {
        const formatted = formatTextForChannel(response, 'slack');
        await say({ text: formatted, thread_ts: threadTs });
      }
    } catch (error) {
      logger.error('Failed to process Slack message', error);
      await say({ text: 'Sorry, I encountered an error processing your request.', thread_ts: threadTs });
    }
  }
}

